// Generated by Suite Builder from a crawl of the site. Runs the suite in Chrome when it is installed, else in Electron (built into Cypress), and says which.
// EDIT RULES: do not edit this file; regenerating replaces all of it. A --browser given wins; every option passes through: npm test -- --browser firefox.
import { spawnSync } from 'node:child_process';
import cypress from 'cypress';

// The suite's rules first: their report, and a warning for each advisory one. A broken hard or story
// rule fails the run at the end; it never stops the tests from running (G-119).
const rules = spawnSync(process.execPath, ['suite-rules/check.mjs'], { stdio: 'inherit' });

const options = await cypress.cli.parseRunArguments(['cypress', 'run', ...process.argv.slice(2)]);
const chosen = options.browser !== undefined;
let result = await cypress.run(chosen ? options : { ...options, browser: 'chrome' });
// No Chrome here: Cypress refuses before any test runs, and Electron always is.
if (!chosen && result.status === 'failed' && /browser/i.test(result.message ?? '') && /chrome/i.test(result.message ?? '')) {
  console.log('Chrome is not installed on this computer: running in Electron, the browser built into Cypress.');
  result = await cypress.run(options);
}
if (result.status === 'failed') console.error(result.message);
if (rules.status !== 0) console.log("The suite's rules are broken (above, and cypress/rules-report.md): the run fails for it.");
process.exit(result.status === 'failed' || result.totalFailed > 0 || rules.status !== 0 ? 1 : 0);
